import type {Unit} from "./types";

/**
 * catalog — ЄДИНИЙ каталог робіт.
 * -------------------------------
 * Зводить докупи те, що раніше жило у двох місцях: lib/defaults.ts (плоскі
 * ставки для Estimates) і lib/calcPricing.ts (labor/material/складність для
 * Calculator). Дві ціни на ту саму роботу були джерелом розбіжностей між
 * вкладками, тому тут кожна робота існує рівно один раз.
 *
 * laborRate / materialRate — за одиницю. materialRate покриває лише монтажні
 * матеріали підрядника (кріплення, клей, thinset, затирка, підводки), а не
 * сам прилад чи оздоблення — їх купує клієнт. Тому materialStatus здебільшого
 * "partial": частина комплекту оцінена, решта ні.
 *
 * marketLow / marketHigh — ринковий орієнтир (Homewyse + звірка по Чикаго),
 * довідково. keepOwnRate означає, що власна ставка навмисно нижча за ринок і
 * масове застосування ринкових ставок цю позицію не чіпає.
 *
 * legacyIds — під якими id ця робота існувала раніше; потрібні, щоб перенести
 * збережені в акаунті ціни без втрат.
 */
export type MaterialStatus="unknown"|"partial"|"priced"|"none";

export type CatalogTask={
  id:string;
  category:string;
  name:string;
  aliases:string[];
  unit:Unit;
  laborRate:number;
  materialRate:number;
  materialStatus:MaterialStatus;
  suppliesPct:number;
  suppliesFixed:number;
  minPrice:number;
  difficultyMultipliers:{basic:number;standard:number;difficult:number};
  lowMult:number;
  highMult:number;
  marketLow?:number;
  marketHigh?:number;
  keepOwnRate?:boolean;
  legacyIds?:string[];
  notes:string;
  source:string;
  sourceUrl?:string;
  checked?:string;
};

